+constexpr size_t INSERTION_SORT_THRESHOLD = 35;
+constexpr size_t PING_PONG_BUFFER_SIZE = 1024 * 1024; // 1MB buffer for ping-pong
+
+static void insertion_sort(uint32_t* a, size_t lo, size_t hi) {
+    for (size_t i = lo + 1; i < hi; ++i) {
+        uint32_t key = a[i];
+        size_t j = i;
+        while (j > lo && a[j - 1] > key) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = key;
+    }
+}
+
+static void merge_sort_rec(uint32_t* a, uint32_t* tmp, uint32_t* ping_pong, size_t lo, size_t hi, bool use_ping_pong) {
     if (hi - lo < 2) return;
+    if (hi - lo <= INSERTION_SORT_THRESHOLD) {
+        insertion_sort(a, lo, hi);
+        return;
+    }
     size_t mid = lo + (hi - lo) / 2;
