+        merge_sort_rec(a, ping_pong, tmp, lo, mid, false);
+        merge_sort_rec(a, ping_pong, tmp, mid, hi, false);
+    } else {
+        merge_sort_rec(a, tmp, ping_pong, lo, mid, false);
+        merge_sort_rec(a, tmp, ping_pong, mid, hi, false);
